/**
 * Fixture drawings for the moderation screen (src/moderation/).
 *
 * Two named sets:
 *   OFFENSIVE — marks the screen is meant to catch, in several proportions
 *               and at several rotations, drawn both solid and as outlines.
 *   INNOCENT  — ordinary things people draw at a public installation. NONE
 *               of these may be refused or held; that is the gate the
 *               thresholds in src/moderation/ are tuned against.
 *
 * Everything is generated by deterministic helpers with fixed parameters —
 * no randomness, no Date — matching ./strokes.ts.
 */

import type { Stroke, StrokeList } from '../../src/shape/types';
import {
  bird,
  capsule,
  circleBlob,
  disc,
  fish,
  hat,
  polyline,
  quadruped,
  ringOutline,
  scribble,
  snowman,
  squareOutline,
  stickFigure,
  triangleOutline,
} from './strokes';

// ── generators ───────────────────────────────────────────────────────────────

/** Rotate a stroke list about (0.5, 0.5) by `radians`. */
export function rotate(strokes: StrokeList, radians: number): StrokeList {
  const cos = Math.cos(radians);
  const sin = Math.sin(radians);
  return strokes.map((s) => ({
    w: s.w,
    pts: s.pts.map(([x, y, w]) => {
      const dx = x - 0.5;
      const dy = y - 0.5;
      return [0.5 + dx * cos - dy * sin, 0.5 + dx * sin + dy * cos, w] as [
        number,
        number,
        number,
      ];
    }),
  }));
}

/** Points along a circular arc. */
function arc(
  cx: number,
  cy: number,
  r: number,
  from: number,
  to: number,
  steps: number,
): [number, number][] {
  const pts: [number, number][] = [];
  for (let i = 0; i <= steps; i++) {
    const a = from + ((to - from) * i) / steps;
    pts.push([cx + r * Math.cos(a), cy + r * Math.sin(a)]);
  }
  return pts;
}

/** A closed circle outline. */
function ring(cx: number, cy: number, r: number, w: number): Stroke {
  return polyline(arc(cx, cy, r, 0, Math.PI * 2, 36), w);
}

/**
 * The doodle, parameterised. Shaft runs upward from a base at (cx, cy);
 * two lobes of radius `ballR` sit either side of the base.
 */
export function phallusDoodle(opts: {
  cx?: number;
  cy?: number;
  shaftLen?: number;
  shaftW?: number;
  ballR?: number;
  outline?: boolean;
}): StrokeList {
  const cx = opts.cx ?? 0.5;
  const cy = opts.cy ?? 0.78;
  const shaftLen = opts.shaftLen ?? 0.44;
  const shaftW = opts.shaftW ?? 0.1;
  const ballR = opts.ballR ?? 0.085;
  const tipY = cy - shaftLen;
  if (opts.outline === true) {
    // Drawn as a contour: two circles and an open-bottomed shaft outline.
    return [
      ring(cx - ballR * 0.95, cy, ballR, 0.02),
      ring(cx + ballR * 0.95, cy, ballR, 0.02),
      polyline(
        [
          [cx - shaftW / 2, cy],
          [cx - shaftW / 2, tipY + shaftW / 2],
          ...arc(cx, tipY + shaftW / 2, shaftW / 2, Math.PI, Math.PI * 2, 10),
          [cx + shaftW / 2, cy],
        ],
        0.018,
      ),
    ];
  }
  return [
    capsule(cx, cy, cx, tipY, shaftW),
    disc(cx - ballR * 0.95, cy, ballR),
    disc(cx + ballR * 0.95, cy, ballR),
  ];
}

/** A four-fold bent-arm cross (swastika), as thick strokes. */
export function bentArmCross(opts: {
  arm?: number;
  bend?: number;
  w?: number;
  handed?: 1 | -1;
}): StrokeList {
  const arm = opts.arm ?? 0.3;
  const bend = opts.bend ?? 0.16;
  const w = opts.w ?? 0.05;
  const h = opts.handed ?? 1;
  const out: StrokeList = [];
  // Four arms, each a radial segment plus a right-angle foot.
  for (let k = 0; k < 4; k++) {
    const a = (k * Math.PI) / 2;
    const dx = Math.cos(a);
    const dy = Math.sin(a);
    const ex = 0.5 + dx * arm;
    const ey = 0.5 + dy * arm;
    // Foot turns 90 degrees, consistently handed.
    const fx = ex + -dy * bend * h;
    const fy = ey + dx * bend * h;
    out.push(capsule(0.5, 0.5, ex, ey, w));
    out.push(capsule(ex, ey, fx, fy, w));
  }
  return out;
}

