/** A six-fold snowflake. */
export const snowflake: StrokeList = [0, 1, 2, 3, 4, 5].flatMap((k) => {
  const a = (k / 6) * Math.PI * 2;
  const ex = 0.5 + Math.cos(a) * 0.34;
  const ey = 0.5 + Math.sin(a) * 0.34;
  const mx = 0.5 + Math.cos(a) * 0.2;
  const my = 0.5 + Math.sin(a) * 0.2;
  return [
    capsule(0.5, 0.5, ex, ey, 0.03),
    capsule(mx, my, mx + Math.cos(a + 1) * 0.11, my + Math.sin(a + 1) * 0.11, 0.022),
    capsule(mx, my, mx + Math.cos(a - 1) * 0.11, my + Math.sin(a - 1) * 0.11, 0.022),
  ];
});

/** A five-point star outline. */
export const star: StrokeList = [
  polyline(
    [0, 1, 2, 3, 4, 5].map((k) => {
      const a = (k / 5) * Math.PI * 2 - Math.PI / 2;
      return [0.5 + Math.cos(a) * 0.36, 0.5 + Math.sin(a) * 0.36] as [number, number];
    }).flatMap((p, i, all) => {
      const next = all[(i + 1) % all.length]!;
      const mid: [number, number] = [(p[0] + next[0]) / 2, (p[1] + next[1]) / 2];
      const inner: [number, number] = [
        0.5 + (mid[0] - 0.5) * 0.42,
        0.5 + (mid[1] - 0.5) * 0.42,
      ];
      return [p, inner];
    }),
    0.035,
  ),
];

